#include <iostream>
#include <string>

int countVowels(const std::string& line) {
    const std::string vowels = "aeiouAEIOU";
    int count = 0;
    for (char ch : line) {
        if (vowels.find(ch) != std::string::npos) {
            count++;
        }
    }
    return count;
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::cout << countVowels(line) << "\n";
    return 0;
}

