package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func countVowels(line string) int {
	count := 0
	for _, ch := range line {
		if strings.ContainsRune("aeiouAEIOU", ch) {
			count++
		}
	}
	return count
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()
	fmt.Println(countVowels(line))
}

